PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS quick_notes (id INTEGER PRIMARY KEY AUTOINCREMENT,source TEXT NOT NULL,source_message_id TEXT NOT NULL,chat_id TEXT,raw_text TEXT NOT NULL,parsed_type TEXT NOT NULL DEFAULT 'quick_note',payment_method TEXT NOT NULL DEFAULT 'belirsiz',status TEXT NOT NULL DEFAULT 'captured',needs_review INTEGER NOT NULL DEFAULT 1 CHECK(needs_review IN(0,1)),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(source,source_message_id));
CREATE TABLE IF NOT EXISTS source_health (source_id TEXT PRIMARY KEY,status TEXT NOT NULL CHECK(status IN('confirmed','stale','estimated','missing','blocked','ok')),code TEXT NOT NULL,message TEXT,last_success_at TEXT,checked_at TEXT NOT NULL,evidence_ref TEXT);
CREATE TABLE IF NOT EXISTS approval_queue (id TEXT PRIMARY KEY,item_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'needs_review',payload_json TEXT NOT NULL,evidence_ref TEXT,idempotency_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),decided_at TEXT,decided_by TEXT);
CREATE TABLE IF NOT EXISTS action_log (id TEXT PRIMARY KEY,action_type TEXT NOT NULL,target_system TEXT NOT NULL,status TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,evidence_ref TEXT,result_json TEXT,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),verified_at TEXT);
CREATE TABLE IF NOT EXISTS decision_log (id TEXT PRIMARY KEY,decision TEXT NOT NULL,thesis TEXT,evidence TEXT,counterargument TEXT,recommendation TEXT,owner TEXT,deadline TEXT,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS entity_aliases (alias_key TEXT PRIMARY KEY,canonical_name TEXT NOT NULL,customer_ref TEXT,supplier_ref TEXT,rule_note TEXT,updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS last_bank_balances (bank_key TEXT PRIMARY KEY,bank_name TEXT NOT NULL,balance REAL NOT NULL,balance_date TEXT NOT NULL,source_ref TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_quick_notes_status_created ON quick_notes(status,created_at);
CREATE INDEX IF NOT EXISTS idx_approval_queue_status_created ON approval_queue(status,created_at);
CREATE INDEX IF NOT EXISTS idx_action_log_status_created ON action_log(status,created_at);
